   583	/**
   584	 * gnutls_pkcs12_get_bag:
   585	 * @pkcs12: A pkcs12 type
   586	 * @indx: contains the index of the bag to extract
   587	 * @bag: An initialized bag, where the contents of the bag will be copied
   588	 *
   589	 * This function will return a Bag from the PKCS12 structure.
   590	 *
   591	 * After the last Bag has been read
   592	 * %GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE will be returned.
   593	 *
   594	 * Returns: On success, %GNUTLS_E_SUCCESS (0) is returned, otherwise a
   595	 *   negative error value.
   596	 **/
   597	int
   598	gnutls_pkcs12_get_bag(gnutls_pkcs12_t pkcs12,
   599	                      int indx, gnutls_pkcs12_bag_t bag)
   600	{
   601	        ASN1_TYPE c2 = ASN1_TYPE_EMPTY;
   602	        int result, len;
   603	        char root2[MAX_NAME_SIZE];
   604	        char oid[MAX_OID_SIZE];
   605	
